      structure = valid_line.structure_name.id

    if select > 1:

      if valid_line.structure_name.id != structure:

          raise UserError("PO Lines with Same Structure Should be Selected!")



    if valid_line.payment_method.lc == True:

      search_lc = env['lc_header'].search([('created_from_purchase_order', '=', valid_line.accounting_purchase_id.id), ('status', '=', ('Posted','Paid'))],limit=1)

      if not search_lc:

        raise UserError('The LC of all the Selected PO Line/ Lines Should be in Posted or Paid State.')



    create_con_lines = env['consignment_line'].create({'consignment_header_id':record.temp_consignment_header_id.id,'accounting_purchase_id':valid_line.accounting_purchase_id.id,'product_id':valid_line.product_id.id,'description':valid_line.description,'payment_method':valid_line.payment_method.id,

      'tariff_code':valid_line.product_id.tariff_code.id,'unit_price':valid_line.unit_price,'currency_id':valid_line.currency_id.id,'delivery_remainder':valid_line.delivery_remainder,'original_delivery_remainder':valid_line.delivery_remainder,'purchase_line_id':valid_line.purchase_line_id.id,'concessional_rate':valid_line.concessional_rate,

      'volume':valid_line.volume,'weight':valid_line.weight})



if select == 0:

 raise UserError("Atleast One Line Should be Selected to Proceed.")



